\pi:\mathcal{C} \rightarrow \mathcal{S}\, , \ \ \ \ p_1,\ldots,p_n: \mathcal{S} \rightarrow \mathcal{C}\, , \ \ \ \
\mathcal{L}\otimes \pi^*\mathcal{B} \rightarrow \mathcal{C}\, .
\end{equation}
